  rawContent = JSON.stringify(item);
}
return [{ json: { source: 'toqan', provider: 'toqan-gateway', response: rawContent } }];

const body = $('Webhook - Script').first().json.body || {};
const topic = body.topic || 'Como a IA cria vídeos virais';
const style = body.style || 'Cyberpunk';
let script = null;
try {
  const inputObj = $input.first().json;
  const r = inputObj.response;
  if (r) script = typeof r === 'string' ? JSON.parse(r.replace(/^```json\s*|\s*```$/g, '')) : r;
} catch (e) {}
if (!script || !script.scenes || script.scenes.length < 3) {
  script = {
    topic,
    style,
    targetDuration: '15s',
    totalWordCount: 34,
    scenes: [
      { order: 1, type: 'hook', timeRange: '0-3s', narrationText: 'Você ainda perde horas editando um único vídeo?', imagePromptEnglish: `Dramatic high contrast opening visual for ${topic}, glowing neon elements, ${style.toLowerCase()} aesthetic, 8k render, vertical 9:16 aspect ratio` },
      { order: 2, type: 'body', timeRange: '3-12s', narrationText: 'O StudioOps conecta roteiristas inteligentes e renderização na nuvem para entregar seus vídeos prontos em segundos.', imagePromptEnglish: `Futuristic holographic workflow animating scenes dynamically, ${style.toLowerCase()} style, cinematic volumetric lighting, 8k, 9:16 aspect ratio` },
      { order: 3, type: 'cta', timeRange: '12-15s', narrationText: 'Comente TESTAR para receber o acesso antecipado agora!', imagePromptEnglish: `Silhouette of a creator pointing to comments with vibrant neon glow, ${style.toLowerCase()} aesthetic, 8k, vertical 9:16` }
    ],
    fullNarration: 'Você ainda perde horas editando um único vídeo? O StudioOps conecta roteiristas inteligentes e renderização na nuvem para entregar seus vídeos prontos em segundos. Comente TESTAR para receber o acesso antecipado agora!'
  };
}
const growth = {
  title: `POV: Quando você descobre ${topic}`.slice(0, 65),
  description: `Assista até o final para entender como viralizar com ${topic}. Comente QUERO! #viral`,
  hashtags: ['#fyp', '#viral', '#tecnologia', '#ia', '#studioops', '#criatividade'],
  callToActionQuestion: 'Você usaria essa automação no seu canal?'
};
return [{ json: { success: true, script, growth, mediaPrompts: script.scenes.map(s => ({ order: s.order, timeRange: s.timeRange, narration: s.narrationText, prompt: s.imagePromptEnglish })) } }];

